contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address[] calldata _tos, uint[] calldata v) public payable {
        // read before-values
        address before_from = c.from();
        address before_caddress = c.caddress();
        bool reverted;
        bool ret;
        // attempt the call and record whether it reverted
        try c.transfer(_tos, v) returns (bool r) { reverted = false; ret = r; } catch { reverted = true; ret = false; }
        // General rule: if the call did not revert then it must have returned true,
        // and the public state variables `from` and `caddress` must be unchanged.
        // If it reverted, we place no further constraints.
        assert(reverted || (ret == true && c.from() == before_from && c.caddress() == before_caddress));
    }
    receive() external payable {}
}

